{
  const toasts = useToasts();
  const dismiss = useDismissToast();
  if (toasts.length === 0) return null;
  return (
    <section aria-label="Notifications" className="pointer-events-none fixed">
      {toasts.map((t) => (
        <Toast
          key={t.id}
          message={t.message}
          action={t.action}
          actions={t.actions}
          onDismiss={() => dismiss(t.id)}
          placement="stacked"
        />
      ))}
    </section>
  );
}

/** Counts the toasts the store holds. */
export function ToastCount(): React.JSX.Element {
  const toasts = useToasts();
  return <span aria-live="polite">{toasts.length}</span>;
}

